<?php
namespace AtlasShipping;
if(!defined('ABSPATH'))exit;
class Admin {
 public function register(){add_action('admin_menu',array($this,'add_menu'));add_action('admin_notices',array($this,'system_notices'));add_action('admin_enqueue_scripts',array($this,'enqueue_assets'));add_action('admin_post_atlas_shipping_save_identity',array($this,'save_identity'));add_action('admin_post_atlas_shipping_delete_identity',array($this,'delete_identity'));}
 public function add_menu(){add_menu_page(__('ATLAS Shipping','atlas-shipping'),__('ATLAS Shipping','atlas-shipping'),'manage_options','atlas-shipping',array($this,'render_landing'),'dashicons-location-alt',58);add_submenu_page('atlas-shipping',__('Identities','atlas-shipping'),__('Identities','atlas-shipping'),'manage_options','atlas-shipping-identities',array($this,'render_identities'));add_submenu_page('atlas-shipping',__('Diagnostics','atlas-shipping'),__('Diagnostics','atlas-shipping'),'manage_options','atlas-shipping-diagnostics',array(new Diagnostics(),'render'));}
 public function enqueue_assets($hook){if(false!==strpos((string)$hook,'atlas-shipping'))wp_enqueue_style('atlas-shipping-admin',ATLAS_SHIPPING_URL.'assets/css/admin.css',array(),ATLAS_SHIPPING_VERSION);}
 public function render_landing(){if(!current_user_can('manage_options'))wp_die(esc_html__('You do not have permission to access this page.','atlas-shipping'));$id=absint(get_option(Activator::OPTION_PAGE_ID));?><div class="wrap atlas-shipping-admin-wrap"><h1><?php esc_html_e('ATLAS Shipping','atlas-shipping');?></h1><div class="atlas-admin-card"><h2><?php esc_html_e('Passwordless authentication foundation','atlas-shipping');?></h2><p><?php printf(esc_html__('Version %s adds approved identities, one-time magic links, and private application sessions.','atlas-shipping'),esc_html(ATLAS_SHIPPING_VERSION));?></p><a class="button button-primary" href="<?php echo esc_url(get_permalink($id));?>"><?php esc_html_e('Open Shipping Application','atlas-shipping');?></a> <a class="button" href="<?php echo esc_url(admin_url('admin.php?page=atlas-shipping-identities'));?>"><?php esc_html_e('Manage Identities','atlas-shipping');?></a></div></div><?php }
 public function render_identities(){if(!current_user_can('manage_options'))wp_die();$edit=isset($_GET['identity'])?Identities::find(absint($_GET['identity'])):null;?><div class="wrap"><h1><?php esc_html_e('Approved Identities','atlas-shipping');?></h1><?php if(isset($_GET['atlas_error'])):?><div class="notice notice-error"><p><?php echo esc_html(sanitize_text_field(wp_unslash($_GET['atlas_error'])));?></p></div><?php endif;?><div class="atlas-admin-card"><h2><?php echo $edit?esc_html__('Edit Identity','atlas-shipping'):esc_html__('Add Identity','atlas-shipping');?></h2><form method="post" action="<?php echo esc_url(admin_url('admin-post.php'));?>"><input type="hidden" name="action" value="atlas_shipping_save_identity"><input type="hidden" name="identity_id" value="<?php echo esc_attr($edit->id??0);?>"><?php wp_nonce_field('atlas_shipping_save_identity');?><table class="form-table"><tr><th><label for="full_name"><?php esc_html_e('Name','atlas-shipping');?></label></th><td><input class="regular-text" id="full_name" name="full_name" required value="<?php echo esc_attr($edit->full_name??'');?>"></td></tr><tr><th><label for="email"><?php esc_html_e('Email','atlas-shipping');?></label></th><td><input class="regular-text" type="email" id="email" name="email" required value="<?php echo esc_attr($edit->email??'');?>"></td></tr><tr><th><label for="role"><?php esc_html_e('Role','atlas-shipping');?></label></th><td><select id="role" name="role"><?php foreach(Identities::roles() as $role):?><option <?php selected($edit->role??'Project Manager',$role);?>><?php echo esc_html($role);?></option><?php endforeach;?></select></td></tr><tr><th><?php esc_html_e('Enabled','atlas-shipping');?></th><td><label><input type="checkbox" name="enabled" value="1" <?php checked(!isset($edit->enabled)||(int)$edit->enabled);?>> <?php esc_html_e('Allow application access','atlas-shipping');?></label></td></tr></table><?php submit_button($edit?__('Update Identity','atlas-shipping'):__('Add Identity','atlas-shipping'));?></form></div><h2><?php esc_html_e('Current Identities','atlas-shipping');?></h2><table class="widefat striped"><thead><tr><th><?php esc_html_e('Name','atlas-shipping');?></th><th><?php esc_html_e('Email','atlas-shipping');?></th><th><?php esc_html_e('Role','atlas-shipping');?></th><th><?php esc_html_e('Enabled','atlas-shipping');?></th><th><?php esc_html_e('Created','atlas-shipping');?></th><th><?php esc_html_e('Last Login','atlas-shipping');?></th><th><?php esc_html_e('Actions','atlas-shipping');?></th></tr></thead><tbody><?php foreach(Identities::all() as $i):?><tr><td><?php echo esc_html($i->full_name);?></td><td><?php echo esc_html($i->email);?></td><td><?php echo esc_html($i->role);?></td><td><?php echo (int)$i->enabled?esc_html__('Yes','atlas-shipping'):esc_html__('No','atlas-shipping');?></td><td><?php echo esc_html(get_date_from_gmt($i->created_at));?></td><td><?php echo $i->last_login_at?esc_html(get_date_from_gmt($i->last_login_at)):esc_html__('Never','atlas-shipping');?></td><td><a href="<?php echo esc_url(admin_url('admin.php?page=atlas-shipping-identities&identity='.(int)$i->id));?>"><?php esc_html_e('Edit','atlas-shipping');?></a> | <a href="<?php echo esc_url(wp_nonce_url(admin_url('admin-post.php?action=atlas_shipping_delete_identity&identity_id='.(int)$i->id),'atlas_shipping_delete_identity'));?>" onclick="return confirm('<?php echo esc_js(__('Delete this identity and its sessions?','atlas-shipping'));?>')"><?php esc_html_e('Delete','atlas-shipping');?></a></td></tr><?php endforeach;?></tbody></table></div><?php }
 public function save_identity(){if(!current_user_can('manage_options'))wp_die();check_admin_referer('atlas_shipping_save_identity');$result=Identities::save(wp_unslash($_POST),absint($_POST['identity_id']??0));$url=admin_url('admin.php?page=atlas-shipping-identities');if(is_wp_error($result))$url=add_query_arg('atlas_error',$result->get_error_message(),$url);wp_safe_redirect($url);exit;}
 public function delete_identity(){if(!current_user_can('manage_options'))wp_die();check_admin_referer('atlas_shipping_delete_identity');Identities::delete(absint($_GET['identity_id']??0));wp_safe_redirect(admin_url('admin.php?page=atlas-shipping-identities'));exit;}
 public function system_notices(){if(!current_user_can('manage_options'))return;$e=(string)get_option(Migrator::OPTION_LAST_ERROR,'');$a=(string)get_option(Authentication::OPTION_LAST_AUTH_ERROR,'');if($e)printf('<div class="notice notice-error"><p><strong>%s</strong> %s</p></div>',esc_html__('ATLAS Shipping requires attention.','atlas-shipping'),esc_html($e));if($a)printf('<div class="notice notice-warning"><p><strong>%s</strong> %s</p></div>',esc_html__('ATLAS Shipping authentication warning.','atlas-shipping'),esc_html__('A protected authentication error was recorded. Review Diagnostics for the safe reason code.','atlas-shipping'));}
}
